        add     x0,a  ; + the dry
        move    a,x:(r0)+
flend:
        nop     
        move    r1,x:(r7+$0c)
        move    r2,x:(r7+$0d)
        move    r3,x:(r7+$0e)
        move    r5,x:(r7+$0f)
        move    r4,x:(r7+$26)
        move    r6,x:(r7+$27)
        move    x:(r7+$2a),r6
        rts     
; ---- a = o/16, r4 = the side's c1 a2 g/8 ----
flside:
        move    a,x0
        move    #>$4fb9ed,a
        sub     x0,a
        asr     a  ; y/32, y = octaves under 20 kHz
        bsr     >flexp
        move    b,x0
        move    #>$5b2f3f,y0
        mpy     y0,x0,a  ; h = theta/2
        bsr     >flsico
        move    x:(r7+$07),x0
        bsr     >flcoef
        move    x:(r7+$1b),a
        asr     #$3,a,a
        move    x:(r7+$1c),x0
        bsr     >fldiv
        move    b,x:(r4+$2)  ; g/8 = (s/8)/c
        rts     
flexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>flxpend
        asr     b
flxpend:
        asl     b
        rts     
flsico:
; a = h -> SW = sin 2h, CW = cos 2h, PP = SW CW, S2T = SW^2
        move    a,x1
        move    a,x0
        mpy     x0,x0,a
        move    a,y0  ; h^2
        move    #>$000680,x0
        mpy     y0,x0,a
        move    #>$011111,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    #>$155555,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    a,x0
        mpy     x1,x0,a
        move    x1,b
        sub     a,b
        move    b,x:(r7+$18)  ; sin h
        move    #>$0000d0,x0
        mpy     y0,x0,a
        move    #>$002d83,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    #>$055555,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a
        move    #>$400000,b
        sub     a,b
        move    b,x0
        mpy     y0,x0,a  ; 1 - cos h
        move    #>$7fffff,b
        sub     a,b
        move    b,x0  ; cos h
        move    x:(r7+$18),y0
        mpy     y0,x0,a
        asl     a
        move    a,x1  ; sin 2h
        move    x1,x:(r7+$1b)
        mpy     y0,y0,b
        asl     b
        move    #>$7fffff,a
        sub     b,a
        move    a,x0  ; cos 2h
        move    x0,x:(r7+$1c)
        mpy     x1,x0,a
        move    a,x:(r7+$19)
        move    x1,y0
        mpy     y0,y0,a
        move    a,x:(r7+$1a)
        rts     
flcoef:
; x0 = kh -> (r4) c1, a2: P, S2 over D = 1 + 2 kh P (r = 1/D by three Newton steps)
        move    x:(r7+$19),y0
        move    #>$400000,a
        mac     y0,x0,a
        move    a,x1  ; d = D/2 in [0.5, 1)
        move    #>$7a8241,a
        add     #>$400000,a
        sub     x1,a
        move    a,y0  ; r ~ 1/D
        move    #>$400000,a
        mac     -x1,y0,a
        add     #>$400000,a
        move    a,x0  ; 1 - d r
        mpy     y0,x0,a
        asl     a
        move    a,y0  ; r = 2 r (1 - d r)
        move    #>$400000,a
        mac     -x1,y0,a
        add     #>$400000,a
        move    a,x0  ; 1 - d r
        mpy     y0,x0,a
        asl     a
        move    a,y0  ; r = 2 r (1 - d r)
        move    #>$400000,a
        mac     -x1,y0,a
        add     #>$400000,a
        move    a,x0  ; 1 - d r
        mpy     y0,x0,a
        asl     a
        move    a,y0  ; r = 2 r (1 - d r)
        move    x:(r7+$19),x0
        mpy     y0,x0,a
        move    a,x1
        move    x1,x:(r4+$1)  ; a2 = P/D
        move    x:(r7+$1a),x0
        mpy     y0,x0,a  ; a3 = S2/D
        move    x:(r7+$07),y0
        mpy     x1,y0,b
        asl     b
        add     a,b
        move    b,x:(r4)  ; c1 = a3 + k a2
        rts     
fldiv:
; a1 / x0 (0 <= a1 < x0) -> b, 24 div steps
        move    a1,a
        andi    #$fe,ccr
        do      #24,>fldvend
        div     x0,a
fldvend:
        nop     
        move    a0,b
        rts     
